    descriptionAdvanced: {
      de: "Singapur, der Stadtstaat an der Südspitze der malaiischen Halbinsel, ist eines der bedeutendsten Finanz- und Handelszentren der Welt. Die Geschichte der modernen Stadt begann 1819 mit der Gründung eines britischen Handelspostens durch Sir Stamford Raffles. Nach der Unabhängigkeit 1965 verwandelte sich Singapur unter der Führung von Lee Kuan Yew in kürzester Zeit von einem Entwicklungsland in eine hochentwickelte Industrienation. Geografisch besteht der Staat aus einer Hauptinsel und über 60 kleineren Inseln, wobei durch massive Landgewinnung die Gesamtfläche stetig vergrößert wurde. Die Wirtschaft basiert auf den Säulen Finanzdienstleistungen, Hochtechnologie, Pharmazie und dem Hafen, der zu den geschäftigsten der Welt zählt. Das Klima ist tropisch-regenwaldartig mit hoher Luftfeuchtigkeit und ganzjährigen Niederschlägen. Demografisch ist Singapur ein faszinierendes Mosaik aus Chinesen, Malaien, Indern und einer großen Gemeinschaft von Expatriates, was sich in einer einzigartigen kulturellen und kulinarischen Vielfalt widerspiegelt. Die Stadt ist weltbekannt für ihre strengen Gesetze, ihre Sauberkeit und ihre beeindruckende Architektur, von den historischen Shophouses in Chinatown bis zu den futuristischen Gardens by the Bay. Als 'Garden City' legt Singapur großen Wert auf städtisches Grün und Nachhaltigkeit. Bildung und Innovation sind zentrale Pfeiler der staatlichen Strategie, wobei die National University of Singapore regelmäßig Spitzenplätze in weltweiten Rankings belegt.",
      hu: "Szingapúr, a Maláj-félsziget déli csücskén elhelyezkedő városállam, a modern urbanizáció és a gazdasági csoda globális szimbóluma. A 19. század elején még csak egy kis halászfalu volt, mielőtt a Brit Kelet-indiai Társaság felismerte stratégiai jelentőségét és szabadkikötőt hozott létre. Az 1965-ös függetlenné válás után az ország rendkívül gyors fejlődésen ment keresztül, mára a világ egyik leggazdagabb és leginnovatívabb államává vált. Szingapúr földrajza korlátozott, ezért az ország folyamatosan növeli területét a tengerből visszanyert földekkel. Gazdaságának motorja a bankszektor, a biotechnológia és a logisztika; kikötője a világkereskedelem egyik legfontosabb csomópontja. A városállam multikulturális jellege meghatározó: a kínai, maláj és tamil lakosság békés együttélése, valamint az angol nyelv hivatalos használata egyedülálló társadalmi modellt hozott létre. Szingapúr híres a 'Zöld Város' koncepciójáról, ahol a felhőkarcolók között buja parkok és vertikális kertek kaptak helyet. A gasztronómia a város szívét jelenti, a 'hawker center'-ekben a világ minden tájáról érkező ízek keverednek. Az oktatási rendszer a világ élvonalába tartozik, nagy hangsúlyt fektetve a technológiai fejlődésre és a fegyelemre. A város biztonsága, tisztasága és ultramodern infrastruktúrája a turisták és a nemzetközi befektetők elsődleges célpontjává teszi.",
      ro: "Singapore, supranumit 'Orașul Leului', este o metropolă insulară situată în sudul Peninsulei Malaya, reprezentând unul dintre cele mai de succes modele de dezvoltare economică din istoria modernă. Fondat ca post comercial britanic în 1819, Singapore și-a câștigat independența în 1965 și a evoluat rapid sub o conducere pragmatică, devenind un centru financiar global și un lider în inovație. Geografic, statul este format dintr-o insulă principală în formă de romb și numeroase insulițe, suprafața sa fiind extinsă constant prin proiecte ambițioase de recuperare a terenului din mare. Economia este extrem de deschisă și se bazează pe servicii financiare, rafinarea petrolului și tehnologia informației. Climatul tropical umed asigură o vegetație luxuriantă pe tot parcursul anului, orașul fiind celebru pentru integrarea naturii în peisajul urban, cum ar fi celebrul aeroport Jewel Changi sau parcul Gardens by the Bay. Populația este o compoziție multietnică vibrantă de chinezi, malaezieni și indieni, fiecare contribuind la patrimoniul cultural și religios al orașului. Singapore este recunoscut la nivel mondial pentru eficiența sistemului său de transport public, pentru standardele ridicate de siguranță și pentru un sistem educațional riguros. Deși este un stat mic, influența sa diplomatică și economică în Asia de Sud-Est este imensă, fiind un nod vital al rutelor maritime internaționale.",
      en: "Singapore City, the vibrant heart of the sovereign island city-state in Southeast Asia, stands as a global pinnacle of financial success and urban planning. Established as a British trading post by Sir Stamford Raffles in 1819, it transitioned into an independent republic in 1965. Since then, Singapore has achieved an extraordinary economic metamorphosis, moving from a low-income nation to a high-income global hub within a few decades. Geographically, it is situated just north of the equator, characterized by its tropical climate and limited natural resources, which necessitated a strategic focus on human capital and international trade. The economy is driven by world-class financial services, manufacturing (electronics and chemicals), and its strategic port, which is among the world's busiest. Demographically, Singapore is a diverse tapestry of Chinese, Malay, Indian, and Eurasian communities, fostering a unique 'multicultural' identity reflected in its four official languages. The city is renowned for its 'City in a Nature' vision, blending towering skyscrapers with lush green spaces and innovative sustainable architecture like the Supertree Grove. It maintains a world-leading education system and is a global leader in healthcare and technology. Known for its strict legal framework and exceptional cleanliness, Singapore remains a top destination for tourism and international business, acting as a gateway between the East and the West.",
    },
