      ro: "O mare zonă rezidențială în nord-estul Singapore, cu o istorie bogată și un puternic spirit comunitar.",
      en: "A large residential town in the north-east of Singapore with a rich history and strong community spirit.",
      es: "Un gran complejo residencial en el noreste de Singapur con una rica historia y un fuerte espíritu comunitario.",
