      pt: ["Hougang MRT liga o distrito à rede do nordeste.", "Hougang Mall e Hougang Central definem o centro da cidade.", "Kovan encontra-se como um nó parcial conhecido no oeste da área.", "Punggol Park é um espaço recreativo importante nas proximidades.", "Hougang é um dos grandes complexos residenciais no nordeste.", "O distrito está fortemente organizado através de corredores de autocarros e eixos residenciais."],
      fr: ["Hougang MRT relie le district au réseau du nord-est.", "Hougang Mall et Hougang Central définissent le centre-ville.", "Kovan se trouve comme un nœud partiel connu à l'ouest de la zone.", "Punggol Park est un espace de loisirs important à proximité.", "Hougang est l'un des grands complexes résidentiels du nord-est.", "Le district est fortement organisé à travers des couloirs de bus et des axes résidentiels."],
