      en: "A vibrant district known for its rich food scene, preserved shophouses, and bustling nightlife.",
      es: "Un barrio animado, conocido por su rica escena culinaria, sus casas comerciales preservadas y su vibrante vida nocturna.",
      pt: "Um bairro animado, conhecido pela sua rica cena culinária, as suas casas comerciais preservadas e a sua vida noturna vibrante.",
