    facts: {
      de: ["Das National Stadium befindet sich hier.", "Der Kallang River ist der längste Fluss in Singapur.", "War der Standort des ersten Zivilflughafens von Singapur."],
      hu: ["Itt található a Nemzeti Stadion.", "A Kallang folyó Szingapúr leghosszabb folyója.", "Itt volt Szingapúr első polgári repülőtere."],
      ro: ["Stadionul Național este situat aici.", "Râul Kallang este cel mai lung râu din Singapore.", "A fost locația primului aeroport civil din Singapore."],
      en: ["The National Stadium is located here.", "The Kallang River is the longest river in Singapore.", "Was the site of Singapore's first civil airport."],
      es: ["El National Stadium se encuentra aquí.", "El río Kallang es el río más largo de Singapur.", "Fue la ubicación del primer aeropuerto civil de Singapur."],
      pt: ["O National Stadium encontra-se aqui.", "O rio Kallang é o rio mais longo de Singapura.", "Foi a localização do primeiro aeroporto civil de Singapura."],
      fr: ["Le National Stadium se trouve ici.", "La rivière Kallang est la plus longue rivière de Singapour.", "C'était le site du premier aéroport civil de Singapour."],
    }, image: "/poi-images/kallang-cities-v2.webp",
    descriptionAdvanced: {
      de: "Kallang ist ein zentral gelegener Stadtteil von Singapur, der eine tiefe Verbindung zur Sport- und Luftfahrtgeschichte des Landes hat. Früher befand sich hier der Kallang Airport, Singapurs erster zweckgebundener internationaler Flughafen, dessen historisches Empfangsgebäude heute ein geschütztes Denkmal ist. Heute ist Kallang vor allem als das sportliche Herz der Nation bekannt, da es den beeindruckenden Singapore Sports Hub beherbergt, zu dem auch das Nationalstadion mit seinem ikonischen Faltdach gehört. Der Kallang River, der längste Fluss Singapurs, schlängelt sich durch das Viertel und bietet eine malerische Kulisse für Wassersportarten wie Drachenbootfahren und Kanufahren. Die Uferpromenaden sind bei Joggern und Radfahrern beliebt und verbinden das Viertel direkt mit dem Marina Bay-Gebiet. Kallang ist zudem ein wichtiger Wohn- und Industriestandort, der eine Mischung aus modernem Stadtleben und historischer Bedeutung bietet. Durch laufende Erneuerungsprojekte wird die Gegend kontinuierlich in einen noch lebendigeren Ort am Wasser verwandelt.",
      hu: "Kallang Szingapúr központi részén elhelyezkedő negyed, amely mélyen kötődik az ország sport- és repüléstörténetéhez. Korábban itt működött a Kallang repülőtér, Szingapúr első célirányosan épített nemzetközi repülőtere, amelynek történelmi épülete ma is védett műemlék. Napjainkban Kallang elsősorban a nemzet sportközpontjaként ismert, itt található ugyanis a lenvűgöző Singapore Sports Hub, amely magában foglalja az ikonikus tetőszerkezetű Nemzeti Stadiont is. A Kallang-folyó, Szingapúr leghosszabb folyója, keresztülkanyarog a negyeden, festői hátteret biztosítva az olyan vízi sportokhoz, mint a sárkányhajózás és a kajakozás. A folyóparti sétányok népszerűek a kocogók és kerékpárosok körében, és közvetlen összeköttetést biztosítanak a Marina Bay területtel. Kallang fontos lakó- és ipari terület is, amely a modern városi élet és a történelmi jelentőség keverékét kínálja. A folyamatban lévő városfejlesztési projektek révén a környék folyamatosan alakul át egy még vibrálóbb vízparti központtá.",
      ro: "Kallang este un district situat central în Singapore, având o legătură profundă cu istoria sportivă și aviatică a țării. În trecut, aici s-a aflat Aeroportul Kallang, primul aeroport internațional construit special în acest scop, a cărui clădire istorică este astăzi un monument protejat. În prezent, Kallang este cunoscut în principal ca inima sportivă a națiunii, găzduind impresionantul Singapore Sports Hub, care include Stadionul Național cu iconicul său acoperiș retractabil. Râul Kallang, cel mai lung râu din Singapore, șerpuiește prin cartier, oferind un cadru pitoresc pentru sporturi nautice precum canotajul și cursele cu bărci dragon. Promenadele de pe malul râului sunt populare printre alergători și bicicliști, conectând districtul direct cu zona Marina Bay. Kallang este, de asemenea, un centru rezidențial și industrial important, oferind un amestec de viață urbană modernă și semnificație istorică. Prin proiectele de regenerare urbană în curs, zona este transformată continuu într-un district de faleză vibrant.",
      en: "Kallang is a centrally located planning area in Singapore with a storied past, deeply rooted in the nation's aviation and sporting history. It was famously the site of the Kallang Airport, Singapore's first purpose-built international gateway, and its historic terminal building remains a gazetted monument today. In the modern era, Kallang has evolved into the premier destination for sports and lifestyle, anchored by the state-of-the-art Singapore Sports Hub and the iconic National Stadium with its massive retractable dome. The Kallang River, Singapore's longest river, flows through the heart of the district, providing a scenic setting for various water sports such as dragon boating, kayaking, and canoeing. The riverside promenades are a favorite among joggers and cyclists, offering a seamless green link to the Marina Bay area. Kallang also hosts a mix of residential estates and light industrial clusters, making it a diverse urban hub. Ongoing redevelopment efforts aim to further revitalize the area into a vibrant waterfront district.",
      es: "Kallang es el distrito donde el paisaje deportivo y de eventos de Singapur se vuelve especialmente visible. El Singapore Sports Hub, con el National Stadium, el Indoor Stadium y el Kallang Wave Mall, representa aquí una gran infraestructura pública, mientras que la cuenca de Kallang y las superficies de agua circundantes dan al lugar un lado abierto. A esto se suman rastros más antiguos como el entorno del antiguo aeropuerto de Kallang y la conexión con los ejes de transporte internos. Kallang no es solo un escenario deportivo, sino un distrito funcional con historia.",
      pt: "Kallang é o distrito onde a paisagem desportiva e de eventos de Singapura se torna especialmente visível. O Singapore Sports Hub, com o National Stadium, o Indoor Stadium e o Kallang Wave Mall, representa aqui uma grande infraestrutura pública, enquanto a bacia de Kallang e as superfícies de água circundantes conferem ao lugar um lado aberto. A isto somam-se vestígios mais antigos como o ambiente do antigo aeroporto de Kallang e a ligação aos eixos de transporte internos. Kallang não é apenas um cenário desportivo, mas um distrito funcional com história.",
      fr: "Kallang est le quartier où le paysage sportif et événementiel de Singapour devient particulièrement visible. Le Singapore Sports Hub, avec le National Stadium, l'Indoor Stadium et le Kallang Wave Mall, représente ici une grande infrastructure publique, tandis que le bassin de Kallang et les surfaces d'eau environnantes donnent au lieu un côté ouvert. À cela s'ajoutent des traces plus anciennes comme l'environnement de l'ancien aéroport de Kallang et la connexion aux axes de transport internes. Kallang n'est pas seulement une scène sportive, mais un quartier fonctionnel avec de l'histoire.",
    },
