      en: ["Home to the National Stadium, featuring the world's largest free-span dome.", "The Kallang River is the longest river in Singapore, stretching 10 kilometers.", "It was the site of Singapore's first international airport (1937-1955).", "The Singapore Indoor Stadium was designed by renowned architect Kenzo Tange.", "Kallang Basin was historically a major center for shipbuilding and repairs.", "The area is a primary hub for water sports like dragon boat racing."],
      es: ["El Singapore Sports Hub define al Kallang moderno.", "El National Stadium es el centro de atención del área.", "El Kallang Wave Mall se encuentra directamente en el complejo deportivo.", "La cuenca de Kallang y el espacio fluvial dan forma a la ubicación.", "El terreno del antiguo aeropuerto de Kallang reside en la memoria histórica del distrito.", "Kallang MRT y las estaciones circundantes aseguran la conexión."],
      pt: ["O Singapore Sports Hub define a Kallang moderna.", "O National Stadium é o centro das atenções da área.", "O Kallang Wave Mall encontra-se diretamente no complexo desportivo.", "A bacia de Kallang e o espaço fluvial dão forma à localização.", "O terreno do antigo aeroporto de Kallang reside na memória histórica do distrito.", "Kallang MRT e as estações circundantes asseguram a ligação."],
      fr: ["Le Singapore Sports Hub définit le Kallang moderne.", "Le National Stadium est le point focal de la zone.", "Le Kallang Wave Mall se trouve directement dans le complexe sportif.", "Le bassin de Kallang et l'espace fluvial façonnent l'emplacement.", "Le terrain de l'ancien aéroport de Kallang réside dans la mémoire historique du quartier.", "Kallang MRT et les stations environnantes assurent la connexion."],
