      hu: ["A név valószínűleg 'vörös hajú ember hídját' jelenti hokkienül.", "Úttörő volt a közlekedési és bevásárlóközpontok integrálásában.", "Itt található az 1992-ben alapított Nanyang Polytechnic.", "Az Ang Mo Kio Hub a negyed jelentős kereskedelmi központja.", "A Town Garden West parkban egy lépcsős domb található.", "Híres az egyetlen kör alakú HDB lakótömbjéről Szingapúrban."],
      ro: ["Numele înseamnă probabil „Podul Omului cu Păr Roșu” în Hokkien.", "Pionier în integrarea nodurilor de transport și retail.", "Găzduiește Nanyang Polytechnic, fondat în 1992.", "Ang Mo Kio Hub este un complex comercial major.", "Town Garden West oferă un peisaj colinar pitoresc.", "Cunoscut pentru singurul bloc HDB circular din Singapore."],
      en: ["The name likely means 'Red-Haired Man's Bridge' in Hokkien.", "The town was a pioneer in integrating transport and retail hubs.", "Home to Nanyang Polytechnic, established in 1992.", "Features the Ang Mo Kio Hub, a major commercial complex.", "Ang Mo Kio Town Garden West has a scenic hill with stairs.", "Known for its circular HDB block, a unique architectural landmark."],
      es: ["AMK Hub es un lugar central de suministro y compras.", "Ang Mo Kio MRT conecta el barrio con la línea Norte-Sur.", "Yio Chu Kang es un importante corredor periférico en la zona.", "El parque Bishan-Ang Mo Kio es fácilmente accesible desde el distrito.", "Las avenidas 1 a 10 definen la estructura urbana.", "Ang Mo Kio es una de las grandes zonas residenciales HDB maduras."],
      pt: ["O AMK Hub é um local central de abastecimento e compras.", "A estação MRT de Ang Mo Kio liga o bairro à linha Norte-Sul.", "Yio Chu Kang é um importante corredor periférico na zona.", "O parque Bishan-Ang Mo Kio é facilmente acessível a partir do distrito.", "As avenidas 1 a 10 definem a estrutura urbana.", "Ang Mo Kio é uma das grandes zonas residenciais HDB maduras."],
      fr: ["L'AMK Hub est un lieu central d'approvisionnement et de shopping.", "La station MRT d'Ang Mo Kio relie le quartier à la ligne Nord-Sud.", "Yio Chu Kang est un important corridor périphérique dans la zone.", "Le parc Bishan-Ang Mo Kio est facilement accessible depuis le quartier.", "Les avenues 1 à 10 définissent la structure urbaine.", "Ang Mo Kio fait partie des grandes zones résidentielles HDB matures."],
