      en: ["Offers scenic views of the sea.", "Parkway Parade is a major shopping mall.", "Direct access to East Coast Park."],
      es: ["Ofrece una vista pintoresca del mar.", "Parkway Parade es un importante centro comercial.", "Acceso directo a East Coast Park."],
      pt: ["Oferece uma vista pitoresca do mar.", "Parkway Parade é um importante centro comercial.", "Acesso direto ao East Coast Park."],
